import{contextualGrowth,initWorld,syncContext}from './world.js';
import{initSocial,changeArea,canMeetFriend,friendPrompt,meetFriend}from './social.js';
// Developmental ranges: Merck Veterinary Manual / Social Behavior of Dogs.
// Individual milestone dates and all story probabilities are game assumptions.
export const SOURCES=[{id:'merck-development',title:'Merck Veterinary Manual · Social Behavior of Dogs',url:'https://www.merckvetmanual.com/behavior/behavior-of-dogs/social-behavior-of-dogs',scope:'전환기 약 13–19일, 사회화기 약 19일–12주, 이유 완료 약 7주. 개체별 차이가 있음.',kind:'발달 참고 자료'}];
export function initStories(s){if(s.storyVersion===2){initSocial(s);return;}s.storyVersion=2;s.stress=20;s.dogBond=0;s.people={caregiver:{name:s.person,available:true}};s.friend={name:'한쪽 귀가 접힌 개',met:false};s.story={moved:false,lost:false,lostAt:null,returnHome:null,reunited:false,care:'normal',careUntil:null};s.milestones={eyes:14+s.seed%5,walking:20+s.seed%6,weaning:46+s.seed%9};s.storyCounts={};initSocial(s);}
export function growth(s,log,remember){contextualGrowth(s,log,remember);if(s.day>=s.milestones.ears&&!s.memories.includes('ears')&&!s.development?.historicalUnknown.includes('ears')){log(s,'ears','잠자리 밖에서 난 작은 소리에 몸이 움찔한다. 따뜻한 몸에 기대다가 고개를 조금 돌려 본다.');s.log.at(-1).source='merck-development';remember(s,'ears')}}
export function storyChoice(s,p,id,log,remember,clamp,random){
if(p.id==='dog-meet')meetFriend(s,id,log,remember,clamp);
if(p.id==='move-house'){s.story.moved=true;changeArea(s,'moving');s.comfort=clamp(s.comfort-8);remember(s,'moving');log(s,'moving',id==='blanket'?'낯선 방에서 예전 담요의 냄새를 찾았다. 그 위에 몸을 눕힌다.':'문가에서 방 안을 살핀다. 낯선 곳에도 익숙한 사람의 냄새가 남아 있다.');s.story.settleAt=s.day+14;}
if(p.id==='open-gate'){if(id==='stay'){log(s,'gate-safe','바깥 냄새를 맡다가 익숙한 발소리 쪽으로 돌아간다.');s.familyBond=clamp(s.familyBond+3)}else{log(s,'gate-out','문밖 냄새를 따라 걷는다. 돌아보니 익숙한 입구가 보이지 않는다.');s.story.lost=true;s.story.lostAt=s.day;s.story.returnHome=s.home;s.story.returnArea=s.areaId;s.story.returnFriend={...s.friend};s.story.returnContext={...s.worldModel.context};s.story.returnResource=s.worldModel.resource;s.story.returnCare=s.worldModel.care;s.home='street';changeArea(s,'lost');syncContext(s);s.stress=clamp(s.stress+25);remember(s,'lost');}}
if(p.id==='lost-help'){s.story.searches=(s.story.searches||0)+1;if(random(s)<(id==='wait'?.7:.2)){s.home=s.story.returnHome||'family';if(s.story.returnArea){s.areaId=s.story.returnArea;s.friend={...s.story.returnFriend};s.dogBond=s.friend.bond;s.worldModel.context={...s.story.returnContext};s.worldModel.contextArea=s.areaId;s.worldModel.resource=s.story.returnResource;s.worldModel.care=s.story.returnCare;}s.story.lost=false;s.story.reunited=true;s.stress=clamp(s.stress-20);remember(s,'reunion');log(s,'reunion','익숙한 목소리에 고개를 든다. 달려온 사람이 몸을 안는다. 손 냄새가 기억과 같다.')}else{log(s,'searching',id==='wait'?'그 자리에서 기다렸지만 익숙한 냄새는 오지 않았다.':'길을 더 살핀다. 모퉁이 너머에도 낯선 냄새뿐이다.');s.story.nextSearch=s.day+7;}}
if(p.id==='alone'){s.stress=clamp(s.stress+(id==='rest'?-4:6));log(s,'alone-result',id==='rest'?'문 옆에서 웅크리고 기다린다. 한참 뒤 익숙한 열쇠 소리가 들린다.':'집 안을 오가며 소리를 낸다. 돌아온 사람이 곁에 앉아 준다.');remember(s,'waiting');}
if(p.id==='care-change'){s.story.care='reduced';s.story.careUntil=s.day+60;log(s,'care-change',id==='near'?'그 사람 곁에 몸을 붙인다. 평소보다 오래 등을 쓰다듬는다.':'장난감을 물고 가만히 기다린다. 오늘은 놀이가 짧다.');remember(s,'quiet-house');}
}
export function storyStep(s,{log,remember,decision,random,clamp}){const t=s.story;
if(t.settleAt&&t.settleAt<=s.day&&!s.memories.includes('settled:'+t.settleAt)){remember(s,'settled:'+t.settleAt);s.comfort=clamp(s.comfort+10);log(s,'settled','잠자리에서 물그릇까지 이제 망설이지 않고 간다. 새집의 소리가 익숙해졌다.');remember(s,'settled')}
if(t.careUntil&&t.careUntil<=s.day&&t.care==='reduced'){t.care='normal';log(s,'care-recovery','다시 정해진 시간에 산책줄이 들린다. 문 앞에서 발을 동동 구른다.');remember(s,'routine-return')}
if(t.lost){const elapsed=s.day-t.lostAt;if(elapsed>=60){t.lost=false;t.longSeparated=true;t.returnHome=null;s.home='street';changeArea(s,'long-separation');syncContext(s);log(s,'lost-long-separation','익숙한 사람이 돌아오지 않은 채 여러 주가 지났다. 새로 물을 찾고 쉬던 길이 생활 범위가 됐다. 예전 가족의 상태는 알 수 없고, 지금 머무는 구역에서 하루를 이어 간다.');remember(s,'long-separation');return true}if(!s.pending&&s.day>=(t.nextSearch??t.lostAt+3)){if((t.searches||0)>=3){t.nextSearch=s.day+14;log(s,'lost-searching','며칠 동안 머물던 길과 쉬던 자리를 오간다. 아직 익숙한 사람과 만나지는 못했다. 물과 마른 잠자리를 찾으며 같은 구역 안에 머문다.');return true}const stages=[['골목 모퉁이에서 발소리가 멈춘다. 처음 지나온 방향과 마른 처마 아래가 모두 보인다.','마지막으로 익숙했던 자리 가까이 머문다','차가 없는 골목 안쪽을 짧게 살핀다'],['며칠째 머문 구역에서 사람이 천천히 둘러본다. 몸을 낮추고 있는 자리에서 그 움직임을 볼 수 있다.','멀리 움직이지 않고 눈에 보이는 곳에 머문다','사람과 거리를 두고 같은 구역을 돌아본다'],['처음 왔던 길 쪽에서 발소리와 부르는 소리가 들린다. 소리가 난 방향과 지금 쉬는 자리 사이에 빈 길이 있다.','탁 트인 쪽에 서서 발소리를 기다린다','붐비지 않는 길로 움직임을 살핀다']];const scene=stages[Math.min(2,t.searches||0)];decision(s,'lost-help',scene[0],[['wait',scene[1]],['search',scene[2]]]);}return true;}
if(s.pending||s.day<90)return false;
initWorld(s);const cal=s.worldModel.calendar;
if(s.day>=cal.friend&&canMeetFriend(s)&&s.friend.meetings>=6&&s.friend.meetings%3!==0){cal.friend=s.day+100+Math.floor(random(s)*100);const scene=friendPrompt(s);if(scene.options.length>=2)meetFriend(s,scene.options[0][0],log,remember,clamp);else log(s,'companion-absent',scene.text);}
const roll=random(s);if(s.day>=cal.friend&&canMeetFriend(s)&&(s.friend.meetings<6||s.friend.meetings%3===0)){cal.friend=s.day+70+Math.floor(random(s)*80);const p=friendPrompt(s);if(p.options.length<2){log(s,'companion-absent',p.text);return true}const actor=s.neighborhood.animals.find(a=>a.id===s.friend.id);actor.asked??={};const key=s.currentEncounter.purpose;if(actor.asked[key]){meetFriend(s,p.options[s.stress>65?p.options.length-1:0][0],log,remember,clamp);return true}actor.asked[key]=s.day;decision(s,'dog-meet',p.text,p.options);return true}
if(s.home==='family'){
if(s.day>365&&!t.moved&&roll<0.0012){decision(s,'move-house','상자들이 쌓였다. 익숙한 물건들이 낯선 방으로 옮겨졌다.',[['blanket','내 담요의 냄새를 찾는다'],['watch','문가에서 주변을 살핀다']]);return true}
if(s.day>300&&!t.reunited&&roll>0.7&&random(s)<0.001&&!(s.storyCounts['open-gate'])){decision(s,'open-gate','문이 잠깐 열렸다. 낯선 냄새가 바람을 타고 들어온다.',[['stay','익숙한 사람 곁에 머문다'],['explore','문밖 냄새를 따라간다']]);return true}
if(s.day>100&&s.worldModel.care<65&&roll<0.005&&!s.storyCounts.alone){decision(s,'alone','집이 조용해졌다. 문 너머로 익숙한 발소리가 멀어진다.',[['rest','익숙한 자리에서 기다린다'],['call','문가에서 소리를 낸다']]);return true}
if(t.care==='normal'&&s.day>365&&s.worldModel.resource<50&&roll<0.002&&!s.storyCounts['care-change']){decision(s,'care-change','산책줄이 걸린 채 며칠이 지났다. 사람들의 목소리가 작아지고 집이 조용하다.',[['near','가까이 가서 몸을 기댄다'],['wait','장난감을 물고 기다린다']]);return true}
}
return false;}
